WITH "CONTACT_BASE" AS 
( 
    SELECT 
            "DVO_SRC1"."CONTACT_HKEY" AS "BASE_OBJECT_H_KEY"
        , "DVO_SRC1"."CONTACT_BK" AS "CONTACT_BK"
        , "SAT_SRC1_1_3"."_AIRBYTE_EXTRACTED_AT" AS "SNAPSHOT__TIMESTAMP"
        , "SAT_SRC1_1_3"."CONTACT_NAME" AS "CONTACT_NAME"
    FROM {{ source('eli_dv_bv', 'hub_contact') }} "DVO_SRC1"
    JOIN {{ ref('sat_ssc_contact_bvv_curr') }} "SAT_SRC1_1_3"
        ON  "DVO_SRC1"."CONTACT_HKEY" = "SAT_SRC1_1_3"."CONTACT_HKEY"
    ORDER BY "DVO_SRC1"."CONTACT_HKEY", "SAT_SRC1_1_3"."_AIRBYTE_EXTRACTED_AT"
)
, "POSITION_BASE" AS 
( 
    SELECT 
            "DVO_SRC4"."POSITION_HKEY" AS "BASE_OBJECT_H_KEY"
        , "DVO_SRC4"."POSITION_BK" AS "POSITION_BK"
        , "SAT_SRC4_1_2"."_AIRBYTE_EXTRACTED_AT" AS "SNAPSHOT__TIMESTAMP"
        , "SAT_SRC4_1_2"."JOB_NAME" AS "JOB_NAME"
        , "SAT_SRC4_1_2"."LOCATION" AS "LOCATION"
        , "SAT_SRC4_1_2"."DOMAIN" AS "DOMAIN"
        , "SAT_SRC4_1_2"."SEGMENT" AS "SEGMENT"
        , "SAT_SRC4_1_2"."JOB_STATUS" AS "JOB_STATUS"
        , "SAT_SRC4_1_2"."DIVISION" AS "DIVISION"
        , "SAT_SRC4_1_2"."CONTACT" AS "CONTACT"
        , "SAT_SRC4_1_2"."LAST_ACTIVITY_DATE" AS "LAST_ACTIVITY_DATE"
        , "SAT_SRC4_1_2"."FUNCTION" AS "FUNCTION"
        , "SAT_SRC4_1_2"."QUALIFIED_DATE" AS "QUALIFIED_DATE"
        , "SAT_SRC4_1_2"."JOB_BOARD" AS "JOB_BOARD"
        , "SAT_SRC4_1_2"."TR1__JOB_STAGE__C" AS "TR1__JOB_STAGE__C"
        , "SAT_SRC4_1_2"."OPEN_DATE" AS "OPEN_DATE"
        , "SAT_SRC4_1_2"."CLOSED_DATE" AS "CLOSED_DATE"
        , "SAT_SRC4_1_2"."SUPPLIER_FRIENDLY" AS "SUPPLIER_FRIENDLY"
        , "SAT_SRC4_1_2"."ACCOUNT_NAME" AS "ACCOUNT_NAME"
        , "SAT_SRC4_1_2"."CLOSED_REASON" AS "CLOSED_REASON"
        , "SAT_SRC4_1_2"."MAXIMUM_BILL_RATE" AS "MAXIMUM_BILL_RATE"
        , "SAT_SRC4_1_2"."MINIMUM_BILL_RATE" AS "MINIMUM_BILL_RATE"
        , "SAT_SRC4_1_2"."NUMBER_OF_CURRENT_OFFERS" AS "NUMBER_OF_CURRENT_OFFERS"
        , "SAT_SRC4_1_2"."ESTIMATED_END_DATE" AS "ESTIMATED_END_DATE"
        , "SAT_SRC4_1_2"."NUMBER_OF_OPENINGS" AS "NUMBER_OF_OPENINGS"
        , "SAT_SRC4_1_2"."PRIMARY_BACKGROUND" AS "PRIMARY_BACKGROUND"
        , "SAT_SRC4_1_2"."FEDERAL" AS "FEDERAL"
        , "SAT_SRC4_1_2"."TOTAL_NUMBER_OF_MATCHES" AS "TOTAL_NUMBER_OF_MATCHES"
        , "SAT_SRC4_1_2"."ESTIMATED_START_DATE" AS "ESTIMATED_START_DATE"
        , "SAT_SRC4_1_2"."TOTAL_NUMBER_OF_PLACEMENTS" AS "TOTAL_NUMBER_OF_PLACEMENTS"
        , "SAT_SRC4_1_2"."TOTAL_SUBMITTALS_TO_HIRING_MANAGER" AS "TOTAL_SUBMITTALS_TO_HIRING_MANAGER"
        , "SAT_SRC4_1_2"."TOTAL_SUBMITTALS_TO_JOB_OWNER" AS "TOTAL_SUBMITTALS_TO_JOB_OWNER"
    FROM {{ source('eli_dv_bv', 'hub_position') }} "DVO_SRC4"
    JOIN {{ ref('sat_bh4sf_position_bvv_curr') }} "SAT_SRC4_1_2"
        ON  "DVO_SRC4"."POSITION_HKEY" = "SAT_SRC4_1_2"."POSITION_HKEY"
    ORDER BY "DVO_SRC4"."POSITION_HKEY", "SAT_SRC4_1_2"."_AIRBYTE_EXTRACTED_AT"
)
, "USER_BASE" AS 
( 	-- This CTE retrieves the user information
    SELECT DISTINCT
            "DVO_SRC5"."USER_HKEY" AS "BASE_OBJECT_H_KEY"
        , "DVO_SRC5"."USER_BK" AS "USER_BK"
        , "SAT_SRC5_1_1"."_AIRBYTE_EXTRACTED_AT" AS "SNAPSHOT__TIMESTAMP"
        , "SAT_SRC5_1_1"."NAME" AS "NAME"
    FROM {{ source('eli_dv_bv', 'hub_user') }} "DVO_SRC5"
    INNER JOIN {{ ref('sat_ssc_user_bvv_curr') }} "SAT_SRC5_1_1" ON  "DVO_SRC5"."USER_HKEY" = "SAT_SRC5_1_1"."USER_HKEY"
    ORDER BY "DVO_SRC5"."USER_HKEY", "SAT_SRC5_1_1"."_AIRBYTE_EXTRACTED_AT"
)
, "RECORDTYPE_BASE" AS 
( 	-- This CTE retrieves the user information
    SELECT DISTINCT
            "DVO_SRC6"."RECORDTYPE_HKEY" AS "BASE_OBJECT_H_KEY"
        , "DVO_SRC6"."ID_BK" AS "ID_BK"
        , "SAT_SRC6_1_1"."_AIRBYTE_EXTRACTED_AT" AS "SNAPSHOT__TIMESTAMP"
        , "SAT_SRC6_1_1"."NAME" AS "NAME"
    FROM {{ source('eli_dv_bv', 'hub_recordtype') }} "DVO_SRC6"
    INNER JOIN {{ ref('sat_ssc_recordtype_bvv_curr') }} "SAT_SRC6_1_1" ON  "DVO_SRC6"."RECORDTYPE_HKEY" = "SAT_SRC6_1_1"."RECORDTYPE_HKEY"
    ORDER BY "DVO_SRC6"."RECORDTYPE_HKEY", "SAT_SRC6_1_1"."_AIRBYTE_EXTRACTED_AT"
)
, "COMPANY_BASE" AS 
( -- This CTE retrieves the company information
		SELECT DISTINCT
			  DVO_SRC3.COMPANY_HKEY AS BASE_OBJECT_H_KEY
			, DVO_SRC3.COMPANY_BK AS COMPANY_BK
			, SAT_SRC1_1_3._AIRBYTE_EXTRACTED_AT AS SNAPSHOT__TIMESTAMP
			, SAT_SRC1_1_3.ACCOUNT_NAME AS ACCOUNT_NAME
		FROM {{ source('eli_dv_bv', 'hub_company') }} DVO_SRC3
		INNER JOIN {{ ref('sat_ssc_company_bvv_curr') }} SAT_SRC1_1_3 ON  DVO_SRC3.COMPANY_HKEY = SAT_SRC1_1_3.COMPANY_HKEY
	)
, "PSTN_CNTCT_CNT" AS 
( 
    SELECT 
            "DVO_SRC2"."POSITION_HKEY" AS "BASE_OBJECT_H_KEY"
        , "DVO_SRC2"."LNA_POSITION_CONTACT_TR1CONTACTC_HKEY" AS "BASE_OBJECT_L_H_KEY"
        , "DVO_SRC2"."CONTACT_TR1CONTACTC_HKEY" AS "BASE_OBJECT_F_H_KEY"
        , ROW_NUMBER() OVER (
            PARTITION BY "DVO_SRC2"."POSITION_HKEY" -- Partition by recruiter department to get the latest department
            ORDER BY "SAT_SRC2_1"."_AIRBYTE_EXTRACTED_AT" DESC -- Order by snapshot timestamp to get the latest
        ) AS "RN"
        , "SAT_SRC2_1"."_AIRBYTE_EXTRACTED_AT" AS "SNAPSHOT__TIMESTAMP"
    FROM {{ source('eli_dv_bv', 'view_lna_position_contact_tr1contactc') }} "DVO_SRC2"
    JOIN {{ ref('view_las_bh4sf_position_contact_tr1contactc_bvv_curr') }} "SAT_SRC2_1" 
        ON "DVO_SRC2"."LNA_POSITION_CONTACT_TR1CONTACTC_HKEY" = "SAT_SRC2_1"."LNA_POSITION_CONTACT_TR1CONTACTC_HKEY"
    ORDER BY "DVO_SRC2"."POSITION_HKEY", "SAT_SRC2_1"."_AIRBYTE_EXTRACTED_AT"
)
, "PSTN_CNTCT_TS" AS 
( 
    SELECT 
            "DVO_SRC3"."POSITION_HKEY" AS "BASE_OBJECT_H_KEY"
        , "DVO_SRC3"."LNA_POSITION_CONTACT_TR1TIMESHEETAPPROVERC_HKEY" AS "BASE_OBJECT_L_H_KEY"
        , "DVO_SRC3"."CONTACT_TR1TIMESHEETAPPROVERC_HKEY" AS "BASE_OBJECT_F_H_KEY"
        , ROW_NUMBER() OVER (
            PARTITION BY "DVO_SRC3"."POSITION_HKEY" -- Partition by recruiter department to get the latest department
            ORDER BY "SAT_SRC3_1"."_AIRBYTE_EXTRACTED_AT" DESC -- Order by snapshot timestamp to get the latest
        ) AS "RN"
        , "SAT_SRC3_1"."_AIRBYTE_EXTRACTED_AT" AS "SNAPSHOT__TIMESTAMP"
    FROM {{ source('eli_dv_bv', 'view_lna_position_contact_tr1timesheetapproverc') }} "DVO_SRC3"
    JOIN {{ ref('view_las_bh4sf_position_contact_tr1timesheetapproverc_bvv_curr') }} "SAT_SRC3_1" 
        ON  "DVO_SRC3"."LNA_POSITION_CONTACT_TR1TIMESHEETAPPROVERC_HKEY" = "SAT_SRC3_1"."LNA_POSITION_CONTACT_TR1TIMESHEETAPPROVERC_HKEY"
    ORDER BY "DVO_SRC3"."POSITION_HKEY", "SAT_SRC3_1"."_AIRBYTE_EXTRACTED_AT"
)
, "PSTN_CNTCT_HM" AS 
( 
    SELECT 
            "DVO_SRC3"."POSITION_HKEY" AS "BASE_OBJECT_H_KEY"
        , "DVO_SRC3"."LNA_POSITION_CONTACT_TR1HIRINGMANAGERC_HKEY" AS "BASE_OBJECT_L_H_KEY"
        , "DVO_SRC3"."CONTACT_TR1HIRINGMANAGERC_HKEY" AS "BASE_OBJECT_F_H_KEY"
        , ROW_NUMBER() OVER (
            PARTITION BY "DVO_SRC3"."POSITION_HKEY" -- Partition by recruiter department to get the latest department
            ORDER BY "SAT_SRC3_1"."_AIRBYTE_EXTRACTED_AT" DESC -- Order by snapshot timestamp to get the latest
        ) AS "RN"
        , "SAT_SRC3_1"."_AIRBYTE_EXTRACTED_AT" AS "SNAPSHOT__TIMESTAMP"
    FROM {{ source('eli_dv_bv', 'view_lna_position_contact_tr1hiringmanagerc') }} "DVO_SRC3"
    JOIN {{ ref('view_las_bh4sf_position_contact_tr1hiringmanagerc_bvv_curr') }} "SAT_SRC3_1" 
        ON  "DVO_SRC3"."LNA_POSITION_CONTACT_TR1HIRINGMANAGERC_HKEY" = "SAT_SRC3_1"."LNA_POSITION_CONTACT_TR1HIRINGMANAGERC_HKEY"
    ORDER BY "DVO_SRC3"."POSITION_HKEY", "SAT_SRC3_1"."_AIRBYTE_EXTRACTED_AT"
)
, "PSTN_USER_REC" AS 
( 
    SELECT 
            "DVO_SRC3"."POSITION_HKEY" AS "BASE_OBJECT_H_KEY"
        , "DVO_SRC3"."LNA_POSITION_USER_TR1SOURCINGRECRUITERC_HKEY" AS "BASE_OBJECT_L_H_KEY"
        , "DVO_SRC3"."USER_TR1SOURCINGRECRUITERC_HKEY" AS "BASE_OBJECT_F_H_KEY"
        , ROW_NUMBER() OVER (
            PARTITION BY "DVO_SRC3"."POSITION_HKEY" -- Partition by recruiter department to get the latest department
            ORDER BY "SAT_SRC3_1"."_AIRBYTE_EXTRACTED_AT" DESC -- Order by snapshot timestamp to get the latest
        ) AS "RN"
        , "SAT_SRC3_1"."_AIRBYTE_EXTRACTED_AT" AS "SNAPSHOT__TIMESTAMP"
    FROM {{ source('eli_dv_bv', 'view_lna_position_user_tr1sourcingrecruiterc') }} "DVO_SRC3"
    JOIN {{ ref('view_las_bh4sf_position_user_tr1sourcingrecruiterc_bvv_curr') }} "SAT_SRC3_1" 
        ON  "DVO_SRC3"."LNA_POSITION_USER_TR1SOURCINGRECRUITERC_HKEY" = "SAT_SRC3_1"."LNA_POSITION_USER_TR1SOURCINGRECRUITERC_HKEY"
    ORDER BY "DVO_SRC3"."POSITION_HKEY", "SAT_SRC3_1"."_AIRBYTE_EXTRACTED_AT"
)
, "PSTN_USER_OWNID" AS 
( 
    SELECT 
            "DVO_SRC3"."POSITION_HKEY" AS "BASE_OBJECT_H_KEY"
        , "DVO_SRC3"."LNA_POSITION_USER_OWNERID_HKEY" AS "BASE_OBJECT_L_H_KEY"
        , "DVO_SRC3"."USER_OWNERID_HKEY" AS "BASE_OBJECT_F_H_KEY"
        , ROW_NUMBER() OVER (
            PARTITION BY "DVO_SRC3"."POSITION_HKEY" -- Partition by recruiter department to get the latest department
            ORDER BY "SAT_SRC3_1"."_AIRBYTE_EXTRACTED_AT" DESC -- Order by snapshot timestamp to get the latest
        ) AS "RN"
        , "SAT_SRC3_1"."_AIRBYTE_EXTRACTED_AT" AS "SNAPSHOT__TIMESTAMP"
    FROM {{ source('eli_dv_bv', 'view_lna_position_user_ownerid') }} "DVO_SRC3"
    JOIN {{ ref('view_las_bh4sf_position_user_ownerid_bvv_curr') }} "SAT_SRC3_1" 
        ON  "DVO_SRC3"."LNA_POSITION_USER_OWNERID_HKEY" = "SAT_SRC3_1"."LNA_POSITION_USER_OWNERID_HKEY"
    ORDER BY "DVO_SRC3"."POSITION_HKEY", "SAT_SRC3_1"."_AIRBYTE_EXTRACTED_AT"
)
, "PSTN_RECTYPE" AS 
( 
    SELECT 
            "DVO_SRC3"."POSITION_HKEY" AS "BASE_OBJECT_H_KEY"
        , "DVO_SRC3"."LNA_POSITION_RECORDTYPE_HKEY" AS "BASE_OBJECT_L_H_KEY"
        , "DVO_SRC3"."RECORDTYPE_HKEY" AS "BASE_OBJECT_F_H_KEY"
        , ROW_NUMBER() OVER (
            PARTITION BY "DVO_SRC3"."POSITION_HKEY" -- Partition by recruiter department to get the latest department
            ORDER BY "SAT_SRC3_1"."_AIRBYTE_EXTRACTED_AT" DESC -- Order by snapshot timestamp to get the latest
        ) AS "RN"
        , "SAT_SRC3_1"."_AIRBYTE_EXTRACTED_AT" AS "SNAPSHOT__TIMESTAMP"
    FROM {{ source('eli_dv_bv', 'view_lna_position_recordtype') }} "DVO_SRC3"
    JOIN {{ ref('view_las_bh4sf_position_recordtype_bvv_curr') }} "SAT_SRC3_1" 
        ON  "DVO_SRC3"."LNA_POSITION_RECORDTYPE_HKEY" = "SAT_SRC3_1"."LNA_POSITION_RECORDTYPE_HKEY"
    ORDER BY "DVO_SRC3"."POSITION_HKEY", "SAT_SRC3_1"."_AIRBYTE_EXTRACTED_AT"
)
, "PSTN_COMPANY" AS 
( 
    SELECT 
            "DVO_SRC3"."POSITION_HKEY" AS "BASE_OBJECT_H_KEY"
        , "DVO_SRC3"."LNA_POSITION_COMPANY_HKEY" AS "BASE_OBJECT_L_H_KEY"
        , "DVO_SRC3"."COMPANY_HKEY" AS "BASE_OBJECT_F_H_KEY"
        , ROW_NUMBER() OVER (
            PARTITION BY "DVO_SRC3"."POSITION_HKEY" -- Partition by recruiter department to get the latest department
            ORDER BY "SAT_SRC3_1"."_AIRBYTE_EXTRACTED_AT" DESC -- Order by snapshot timestamp to get the latest
        ) AS "RN"
        , "SAT_SRC3_1"."_AIRBYTE_EXTRACTED_AT" AS "SNAPSHOT__TIMESTAMP"
    FROM {{ source('eli_dv_bv', 'view_lna_position_company') }} "DVO_SRC3"
    JOIN {{ ref('view_las_bh4sf_position_company_bvv_curr') }} "SAT_SRC3_1" 
        ON  "DVO_SRC3"."LNA_POSITION_COMPANY_HKEY" = "SAT_SRC3_1"."LNA_POSITION_COMPANY_HKEY"
    ORDER BY "DVO_SRC3"."POSITION_HKEY", "SAT_SRC3_1"."_AIRBYTE_EXTRACTED_AT"
)
SELECT DISTINCT
     UPPER(SHA2(
        UPPER(REPLACE(COALESCE(TRIM(POSITION_BASE.POSITION_BK),'~'), '\#', '\\\#')) || '\#' ||
        UPPER(REPLACE(COALESCE(TRIM(TO_CHAR(POSITION_BASE.SNAPSHOT__TIMESTAMP, 'DD/MM/YYYY HH24:MI:SS')),'~'), '\#', '\\\#')) || '\#'
    )) AS DIM_POSITION_HKEY
    , "POSITION_BASE"."BASE_OBJECT_H_KEY" AS "BASE_OBJECT_H_KEY"
    , "POSITION_BASE"."POSITION_BK" AS "POSITION_BK"
    , "POSITION_BASE"."SNAPSHOT__TIMESTAMP" AS "SNAPSHOT__TIMESTAMP"
    , "CONTACT_NAME"."CONTACT_NAME" AS "CONTACT_NAME"
    , "CONTACT_TS"."CONTACT_NAME" AS "TIMESHEET_APPROVER"
    , "CONTACT_HM"."CONTACT_NAME" AS "HIRING_MANAGER"
    , "USER_REC"."NAME" AS "ASSIGNED_RECRUITER"
    , "USER_OWNID"."NAME" AS "JOB_OWNER"
    , "COMPANY"."ACCOUNT_NAME" AS "ACCOUNT_NAME"
    , "RECTYPE"."NAME" AS "RECORD_TYPE"
    , "POSITION_BASE"."JOB_NAME" AS "JOB_NAME"
    , "POSITION_BASE"."LOCATION" AS "LOCATION"
    , "POSITION_BASE"."DOMAIN" AS "DOMAIN"
    , "POSITION_BASE"."SEGMENT" AS "SEGMENT"
    , "POSITION_BASE"."JOB_STATUS" AS "JOB_STATUS"
    , "POSITION_BASE"."DIVISION" AS "DIVISION"
    , "POSITION_BASE"."CONTACT" AS "CONTACT"
    , "POSITION_BASE"."LAST_ACTIVITY_DATE" AS "LAST_ACTIVITY_DATE"
    , "POSITION_BASE"."FUNCTION" AS "FUNCTION"
    , "POSITION_BASE"."QUALIFIED_DATE" AS "QUALIFIED_DATE"
    , "POSITION_BASE"."JOB_BOARD" AS "JOB_BOARD"
    , "POSITION_BASE"."TR1__JOB_STAGE__C" AS "TR1__JOB_STAGE__C"
    , "POSITION_BASE"."OPEN_DATE" AS "OPEN_DATE"
    , "POSITION_BASE"."CLOSED_DATE" AS "CLOSED_DATE"
    , "POSITION_BASE"."SUPPLIER_FRIENDLY" AS "SUPPLIER_FRIENDLY"
    , "POSITION_BASE"."CLOSED_REASON" AS "CLOSED_REASON"
    , "POSITION_BASE"."MAXIMUM_BILL_RATE" AS "MAXIMUM_BILL_RATE"
    , "POSITION_BASE"."MINIMUM_BILL_RATE" AS "MINIMUM_BILL_RATE"
    , "POSITION_BASE"."NUMBER_OF_CURRENT_OFFERS" AS "NUMBER_OF_CURRENT_OFFERS"
    , "POSITION_BASE"."ESTIMATED_END_DATE" AS "ESTIMATED_END_DATE"
    , "POSITION_BASE"."NUMBER_OF_OPENINGS" AS "NUMBER_OF_OPENINGS"
    , "POSITION_BASE"."PRIMARY_BACKGROUND" AS "PRIMARY_BACKGROUND"
    , "POSITION_BASE"."FEDERAL" AS "FEDERAL"
    , "POSITION_BASE"."TOTAL_NUMBER_OF_MATCHES" AS "TOTAL_NUMBER_OF_MATCHES"
    , "POSITION_BASE"."ESTIMATED_START_DATE" AS "ESTIMATED_START_DATE"
    , "POSITION_BASE"."TOTAL_SUBMITTALS_TO_HIRING_MANAGER" AS "TOTAL_SUBMITTALS_TO_HIRING_MANAGER"
    , "POSITION_BASE"."TOTAL_NUMBER_OF_PLACEMENTS" AS "TOTAL_NUMBER_OF_PLACEMENTS"
    , "POSITION_BASE"."TOTAL_SUBMITTALS_TO_JOB_OWNER" AS "TOTAL_SUBMITTALS_TO_JOB_OWNER"
FROM "POSITION_BASE" -- Position
-- Get the contact name for the position
JOIN "PSTN_CNTCT_CNT" ON "POSITION_BASE"."BASE_OBJECT_H_KEY" = "PSTN_CNTCT_CNT"."BASE_OBJECT_H_KEY"
    AND "PSTN_CNTCT_CNT"."RN" = 1
JOIN "CONTACT_BASE" "CONTACT_NAME" ON "PSTN_CNTCT_CNT"."BASE_OBJECT_F_H_KEY" = "CONTACT_NAME"."BASE_OBJECT_H_KEY"
-- Get the timesheet approver name for the position
JOIN "PSTN_CNTCT_TS" ON "POSITION_BASE"."BASE_OBJECT_H_KEY" = "PSTN_CNTCT_TS"."BASE_OBJECT_H_KEY"
    AND "PSTN_CNTCT_TS"."RN" = 1
JOIN "CONTACT_BASE" "CONTACT_TS" ON "PSTN_CNTCT_TS"."BASE_OBJECT_F_H_KEY" = "CONTACT_TS"."BASE_OBJECT_H_KEY"
-- Get the hiring manager name for the position
JOIN "PSTN_CNTCT_HM" ON "POSITION_BASE"."BASE_OBJECT_H_KEY" = "PSTN_CNTCT_HM"."BASE_OBJECT_H_KEY"
    AND "PSTN_CNTCT_HM"."RN" = 1
JOIN "CONTACT_BASE" "CONTACT_HM" ON "PSTN_CNTCT_HM"."BASE_OBJECT_F_H_KEY" = "CONTACT_HM"."BASE_OBJECT_H_KEY"
-- Get the assigned recruiter name for the position
JOIN "PSTN_USER_REC" ON "POSITION_BASE"."BASE_OBJECT_H_KEY" = "PSTN_USER_REC"."BASE_OBJECT_H_KEY"
    AND "PSTN_USER_REC"."RN" = 1
JOIN "USER_BASE" "USER_REC" ON "PSTN_USER_REC"."BASE_OBJECT_F_H_KEY" = "USER_REC"."BASE_OBJECT_H_KEY"
-- Get the job owner id for the position
JOIN "PSTN_USER_OWNID" ON "POSITION_BASE"."BASE_OBJECT_H_KEY" = "PSTN_USER_OWNID"."BASE_OBJECT_H_KEY"
    AND "PSTN_USER_OWNID"."RN" = 1
JOIN "USER_BASE" "USER_OWNID" ON "PSTN_USER_OWNID"."BASE_OBJECT_F_H_KEY" = "USER_OWNID"."BASE_OBJECT_H_KEY"
-- Get the record type for the position
JOIN "PSTN_RECTYPE" ON "POSITION_BASE"."BASE_OBJECT_H_KEY" = "PSTN_RECTYPE"."BASE_OBJECT_H_KEY"
    AND "PSTN_RECTYPE"."RN" = 1
JOIN "RECORDTYPE_BASE" "RECTYPE" ON "PSTN_RECTYPE"."BASE_OBJECT_F_H_KEY" = "RECTYPE"."BASE_OBJECT_H_KEY"
-- Get the account for the position
JOIN "PSTN_COMPANY" ON "POSITION_BASE"."BASE_OBJECT_H_KEY" = "PSTN_COMPANY"."BASE_OBJECT_H_KEY"
    AND "PSTN_COMPANY"."RN" = 1
JOIN "COMPANY_BASE" "COMPANY" ON "PSTN_COMPANY"."BASE_OBJECT_F_H_KEY" = "COMPANY"."BASE_OBJECT_H_KEY"